package net.civeira.phylax.features.access.userinvitation.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class MetadataJsonVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property metadata json of user invitation ")
  void test_metadata_json_v_o_builder() {
    Assertions.assertFalse(MetadataJsonVO.nullValue().getMetadataJson().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(MetadataJsonVO.tryFrom(null).getMetadataJson().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one", MetadataJsonVO.from("one").getMetadataJson().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> MetadataJsonVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", MetadataJsonVO.from("one").toString());
  }
}
